<script setup>
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import client from '@/api/client'
const route = useRoute(), item = ref(null), mechanics = ref([]), services = ref([]), spareparts = ref([]), error = ref(''), loading = ref(false)
const mechanicId = ref(''), serviceId = ref(''), partId = ref(''), qty = ref(1), discount = ref(0), method = ref('tunai'), amount = ref(0), note = ref('')
const id = () => route.params.id
async function load() { loading.value = true; try { const [order, m, s, p] = await Promise.all([client.get(`/work-orders/${id()}`), client.get('/mechanics'), client.get('/services'), client.get('/spareparts')]); item.value = order.data.data; mechanics.value = m.data.data; services.value = s.data.data; spareparts.value = p.data.data } catch (e) { error.value = e.response?.data?.message || 'Data gagal dimuat.' } finally { loading.value = false } }
async function act(url, data = {}, verb = 'post') { error.value = ''; try { await client[verb](url, data); await load() } catch (e) { error.value = e.response?.data?.message || 'Aksi ditolak.' } }
function start() { return act(`/work-orders/${id()}/start`, { mechanic_id: mechanicId.value }) }
function addService() { return act(`/work-orders/${id()}/services`, { service_id: serviceId.value }) }
function addPart() { return act(`/work-orders/${id()}/parts`, { sparepart_id: partId.value, qty: qty.value }) }
function finish() { return act(`/work-orders/${id()}/finish`, { discount: discount.value }) }
function pay() { return act(`/work-orders/${id()}/pay`, { method: method.value, amount: amount.value }) }
function saveNote() { return act(`/work-orders/${id()}/public-note`, { public_note: note.value }, 'patch') }
onMounted(load)
</script>
<template><main><h1 class="text-2xl font-bold text-forest">Order {{ item?.queue_number_display }}</h1><div v-if="error" class="service-alert">{{ error }}</div><div v-if="loading">Memuat...</div><template v-if="item"><p>{{ item.vehicle?.plate_number }} · {{ item.status }}<br>{{ item.complaint }}</p><div v-if="item.status === 'menunggu'" class="service-service-card p-4 mb-6"><select v-model="mechanicId" class="service-input mb-3"><option value="">Pilih mekanik</option><option v-for="m in mechanics" :value="m.id">{{ m.name }}</option></select><button class="service-primary" :disabled="!mechanicId" @click="start">Mulai</button></div><div v-if="item.status === 'dikerjakan'" class="service-service-card p-4 mb-6"><div class="input-group mb-3"><select v-model="serviceId" class="service-input"><option value="">Tambah jasa</option><option v-for="s in services" :value="s.id">{{ s.name }}</option></select><button class="service-primary border border-forest bg-transparent text-forest hover:bg-forest-soft" :disabled="!serviceId" @click="addService">Tambah</button></div><div class="input-group mb-3"><select v-model="partId" class="service-input"><option value="">Tambah sparepart</option><option v-for="p in spareparts" :value="p.id">{{ p.name }} ({{ p.stock }})</option></select><input v-model.number="qty" type="number" min="1" class="service-input"><button class="service-primary border border-forest bg-transparent text-forest hover:bg-forest-soft" :disabled="!partId" @click="addPart">Tambah</button></div><input v-model.number="discount" type="number" min="0" class="service-input mb-3" placeholder="Diskon"><button class="service-primary" @click="finish">Selesai</button></div><div class="service-service-card p-4 mb-6"><textarea v-model="note" class="service-input mb-3" placeholder="Catatan publik"></textarea><button class="service-muted" @click="saveNote">Simpan catatan</button></div><div v-if="item.status === 'selesai'" class="service-service-card p-4 mb-6"><select v-model="method" class="service-input mb-3"><option value="tunai">Tunai</option><option value="transfer">Transfer</option><option value="qris">QRIS</option></select><input v-model.number="amount" type="number" min="0" class="service-input mb-3" placeholder="Jumlah bayar"><button class="service-primary" @click="pay">Bayar</button></div><button v-if="!['dibayar','batal'].includes(item.status)" class="service-danger" @click="act(`/work-orders/${id()}/cancel`)">Batalkan</button> <RouterLink class="service-muted ms-2" :to="`/work-orders/${item.id}/receipt`">Struk</RouterLink></template></main></template>
